#!/usr/bin/env node
// Stand-in for Prettier 3's CLI, so verify/js-tools.mjs runs offline. It does what PyIDE asks of the real one:
// `--version`, and `--stdin-filepath <file>` with the text on stdin: the file's .prettierrc (JSON, found from its
// folder up: semi, tabWidth) and the .prettierignore in the working folder apply; JavaScript is re-indented by
// bracket depth with semicolons added or removed, JSON re-printed; unbalanced brackets are a SyntaxError (exit 2, the
// message on stderr as "[error] <file>: SyntaxError: … (line:col)"). Each run is logged to node_modules/.standin-calls.log.
const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
try { fs.appendFileSync(path.join(__dirname, '..', '..', '.standin-calls.log'), `prettier ${args.join(' ')}\n`); } catch {}
if (args.includes('--version')) { process.stdout.write('3.0.0-standin\n'); process.exit(0); }
const at = args.indexOf('--stdin-filepath');
const file = at >= 0 ? path.resolve(args[at + 1]) : null;

function config(dir) {
  for (let d = dir; ; d = path.dirname(d)) {
    const p = path.join(d, '.prettierrc');
    if (fs.existsSync(p)) return JSON.parse(fs.readFileSync(p, 'utf8'));
    if (path.dirname(d) === d) return {};
  }
}

function ignored(f) {
  let lines = [];
  try { lines = fs.readFileSync(path.join(process.cwd(), '.prettierignore'), 'utf8').split(/\r?\n/).map((l) => l.trim()).filter((l) => l && !l.startsWith('#')); } catch {}
  const rel = path.relative(process.cwd(), f).replace(/\\/g, '/');
  return lines.some((pat) => {
    const re = new RegExp(`^${pat.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '[^/]*')}$`);
    return re.test(rel) || re.test(path.basename(f));
  });
}

class SyntaxErr extends Error {}
const OPEN = { '(': ')', '[': ']', '{': '}' };
function checkBrackets(text) {
  const stack = [];
  let line = 1;
  let col = 0;
  let quote = null;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '\n') { line++; col = 0; continue; }
    col++;
    if (quote) { if (c === '\\') i++; else if (c === quote) quote = null; continue; }
    if (c === '"' || c === "'" || c === '`') { quote = c; continue; }
    if (OPEN[c]) stack.push({ c, line, col });
    else if (')]}'.includes(c)) {
      const top = stack.pop();
      if (!top || OPEN[top.c] !== c) throw new SyntaxErr(`Unexpected token (${line}:${col})`);
    } else if (c === ';' && stack.length && stack[stack.length - 1].c === '(') throw new SyntaxErr(`Unexpected token, expected "," (${line}:${col})`);
  }
  if (stack.length) throw new SyntaxErr(`Unexpected token (${line}:${col + 1})`);
}

function formatJs(text, opts) {
  checkBrackets(text);
  const semi = opts.semi !== false;
  const unit = ' '.repeat(opts.tabWidth || 2);
  const out = [];
  let depth = 0;
  for (const raw of text.split(/\r?\n/)) {
    let line = raw.trim();
    if (!line) { if (out.length && out[out.length - 1] !== '') out.push(''); continue; }
    if (!line.startsWith('//')) {
      const had = /;$/.test(line);
      line = line.replace(/\s*;$/, '');
      if (semi && (had || (!/[{([,]$/.test(line) && !/^[})\]]$/.test(line)))) line += ';';
    }
    const opens = (line.match(/[{([]/g) || []).length;
    const closes = (line.match(/[})\]]/g) || []).length;
    if (/^[})\]]/.test(line)) depth = Math.max(0, depth - 1);
    out.push(unit.repeat(depth) + line);
    depth = Math.max(0, depth + opens - closes + (/^[})\]]/.test(line) ? 1 : 0));
  }
  while (out.length && out[out.length - 1] === '') out.pop();
  return `${out.join('\n')}\n`;
}

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (d) => (input += d));
process.stdin.on('end', () => {
  if (!file || ignored(file)) { process.stdout.write(input); return; }
  const opts = config(path.dirname(file));
  try {
    const ext = path.extname(file).toLowerCase();
    let out = input;
    if (ext === '.json') out = `${JSON.stringify(JSON.parse(input), null, opts.tabWidth || 2)}\n`;
    else if (/^\.(js|jsx|mjs|cjs|ts|tsx|mts|cts)$/.test(ext)) out = formatJs(input, opts);
    process.stdout.write(out);
  } catch (err) {
    const rel = path.relative(process.cwd(), file).replace(/\\/g, '/');
    const kind = err instanceof SyntaxErr || err instanceof SyntaxError ? 'SyntaxError' : 'Error';
    process.stderr.write(`[error] ${rel}: ${kind}: ${err.message}\n[error] > 1 | ${input.split(/\r?\n/)[0]}\n`);
    process.exitCode = 2;
  }
});
